core_reasoning_1:
\section*{Claim}
For every integer $q\geq 2$, let $\mathcal S:=\{1,\ldots,q\}$ and let the overlapping-pair transfer matrix $T$ be indexed by ordered pairs $|a,b\rangle$ with $a,b\in\mathcal S$.  If
\[
x:=e^{\beta J_2},\qquad y:=e^{\beta J_1/2},
\]
and
\[
|\psi_1\rangle:=\frac{1}{\sqrt q}\sum_{s\in\mathcal S}|s,s\rangle,
\qquad
|\psi_2\rangle:=\frac{1}{\sqrt{q(q-1)}}\sum_{\substack{s,t\in\mathcal S\\s\ne t}}|s,t\rangle,
\]
then $\mathcal M:=\operatorname{span}\{|\psi_1\rangle,|\psi_2\rangle\}$ is invariant under $T$, and the matrix of $T|_{\mathcal M}$ in the ordered basis $(|\psi_1\rangle,|\psi_2\rangle)$ is
\[
T_2=
\begin{pmatrix}
xy^2 & \sqrt{q-1}\,y\\
\sqrt{q-1}\,y & x+q-2
\end{pmatrix}.
\]

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &q\in\mathbb N,\quad q\geq 2,\quad \mathcal S:=\{1,\ldots,q\}.\\
\text{(P2)}\quad &\langle a,b|c,d\rangle=\delta(a,c)\delta(b,d)\quad\text{for all }a,b,c,d\in\mathcal S.\\
\text{(P3)}\quad &\delta(r,s)=1\text{ if }r=s,\quad \delta(r,s)=0\text{ if }r\ne s.\\
\text{(P4)}\quad &x:=e^{\beta J_2}>0,\quad y:=e^{\beta J_1/2}>0.\\
\text{(P5)}\quad &\langle a,b|T|a',b'\rangle
=\delta(b,a')x^{\delta(a,b')}y^{\delta(a,b)+\delta(a',b')}.
\end{aligned}
\]

\section*{Derivation}
First compute the action of $T$ on $|\psi_1\rangle$:
\begin{align}
\langle a,b|T|\psi_1\rangle
&=\frac{1}{\sqrt q}\sum_{s\in\mathcal S}\langle a,b|T|s,s\rangle
&&\text{by the definition of }|\psi_1\rangle,\\
&=\frac{1}{\sqrt q}\sum_{s\in\mathcal S}\delta(b,s)x^{\delta(a,s)}y^{\delta(a,b)+\delta(s,s)}
&&\text{by (P5)},\\
&=\frac{1}{\sqrt q}x^{\delta(a,b)}y^{\delta(a,b)+1}
&&\text{using the unique term }s=b,\\
&=\begin{cases}
xy^2/\sqrt q, & a=b,\\
y/\sqrt q, & a\ne b,
\end{cases}
&&\text{by (P3)}.
\end{align}
Because the coefficient is constant on the diagonal orbit $a=b$ and constant on the off-diagonal orbit $a\ne b$,
\begin{align}
T|\psi_1\rangle
&=xy^2\left(\frac{1}{\sqrt q}\sum_{a\in\mathcal S}|a,a\rangle\right)
+\sqrt{q-1}\,y\left(\frac{1}{\sqrt{q(q-1)}}\sum_{\substack{a,b\in\mathcal S\\a\ne b}}|a,b\rangle\right)\\
&=xy^2|\psi_1\rangle+\sqrt{q-1}\,y|\psi_2\rangle.
\end{align}
Next compute the action of $T$ on $|\psi_2\rangle$:
\begin{align}
\langle a,b|T|\psi_2\rangle
&=\frac{1}{\sqrt{q(q-1)}}\sum_{\substack{s,t\in\mathcal S\\s\ne t}}
\langle a,b|T|s,t\rangle
&&\text{by the definition of }|\psi_2\rangle,\\
&=\frac{1}{\sqrt{q(q-1)}}\sum_{\substack{s,t\in\mathcal S\\s\ne t}}
\delta(b,s)x^{\delta(a,t)}y^{\delta(a,b)+\delta(s,t)}
&&\text{by (P5)},\\
&=\frac{y^{\delta(a,b)}}{\sqrt{q(q-1)}}\sum_{\substack{t\in\mathcal S\\t\ne b}}x^{\delta(a,t)}
&&\text{set }s=b\text{ and use }t\ne b.
\end{align}
If $a=b$, then $t\ne a$ for every term, so $\delta(a,t)=0$ and
\begin{align}
\langle a,a|T|\psi_2\rangle
&=\frac{y}{\sqrt{q(q-1)}}\sum_{\substack{t\in\mathcal S\\t\ne a}}1
=\frac{(q-1)y}{\sqrt{q(q-1)}}
=\frac{\sqrt{q-1}\,y}{\sqrt q}.
\end{align}
If $a\ne b$, then among the $q-1$ values $t\ne b$ exactly one value is $t=a$, and the remaining $q-2$ values have $t\ne a$; hence
\begin{align}
\langle a,b|T|\psi_2\rangle
&=\frac{1}{\sqrt{q(q-1)}}\left(x+(q-2)\right).
\end{align}
Therefore
\begin{align}
T|\psi_2\rangle
&=\sqrt{q-1}\,y|\psi_1\rangle+(x+q-2)|\psi_2\rangle.
\end{align}
Combining the two column actions gives
\begin{align}
[T]_{(|\psi_1\rangle,|\psi_2\rangle)}
&=\begin{pmatrix}
xy^2 & \sqrt{q-1}\,y\\
\sqrt{q-1}\,y & x+q-2
\end{pmatrix}.
\end{align}

\section*{Final Result}
\[
\boxed{\mathcal M\text{ is }T\text{-invariant and }T|_{\mathcal M}=
\begin{pmatrix}
xy^2 & \sqrt{q-1}\,y\\
\sqrt{q-1}\,y & x+q-2
\end{pmatrix}.}
\]
\hfill$\blacksquare$

core_reasoning_2:
\section*{Claim}
For the one-dimensional $J_1-J_2$ $q$-state Potts chain with $q\geq 2$, let
\[
T_2:=\begin{pmatrix}u&w\\w&v\end{pmatrix}
=\begin{pmatrix}xy^2&\sqrt{q-1}\,y\\\sqrt{q-1}\,y&x+q-2\end{pmatrix},
\quad x:=e^{\beta J_2},\quad y:=e^{\beta J_1/2}.
\]
If $T'$ is the positive zigzag-ladder transfer matrix satisfying $T'=T^2$, then the thermodynamic one-step transfer factor is
\[
\lambda=\frac{u+v}{2}+\sqrt{\left(\frac{u-v}{2}\right)^2+w^2},
\]
and the thermodynamic free energy per spin is
\[
f=-\frac{1}{\beta}\ln\lambda.
\]

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &q\in\mathbb N,
\quad q\geq 2,
\quad x:=e^{\beta J_2}>0,
\quad y:=e^{\beta J_1/2}>0.\\
\text{(P2)}\quad &u:=xy^2,
\quad w:=\sqrt{q-1}\,y,
\quad v:=x+q-2,
\quad T_2:=\begin{pmatrix}u&w\\w&v\end{pmatrix}.\\
\text{(P3)}\quad &T\text{ is the overlapping-pair transfer matrix, }T'\text{ is the zigzag-ladder transfer matrix, and }T'=T^2.\\
\text{(P4)}\quad &\mathcal M\text{ is the two-dimensional maximally symmetric subspace fixed by Potts-label permutations,}\\
&\text{and the matrix of }T|_{\mathcal M}\text{ in the ordered MSS basis is }T_2.\\
\text{(P5)}\quad &T'\text{ has strictly positive entries and commutes with every Potts-label permutation matrix }R.\\
\text{(P6)}\quad &\text{If }A>0\text{ is finite, then }\rho(A)>0\text{ has a unique strictly positive eigenvector up to scale,}\\
&\text{and every other eigenvalue }\eta\text{ satisfies }|\eta|<\rho(A).\\
\text{(P7)}\quad &\text{The fixed subspace of the Potts-label permutation action on ordered pairs is exactly }\mathcal M.\\
\text{(P8)}\quad &Z_N=\operatorname{Tr}(T^{2N})=\operatorname{Tr}((T')^N),
\qquad
f:=\lim_{N\to\infty}-\frac{1}{2N\beta}\ln Z_N.\\
\text{(P9)}\quad &\text{If }A\text{ is finite and has a simple eigenvalue }\rho(A)>|\eta|\text{ for every other eigenvalue }\eta,\\
&\text{then }\displaystyle \lim_{N\to\infty}\frac{1}{N}\ln\operatorname{Tr}(A^N)=\ln\rho(A).
\end{aligned}
\]

\section*{Derivation}
Let $p$ be the strictly positive eigenvector of $T'$ for $\rho(T')$.  For any Potts-label permutation matrix $R$,
\begin{align}
T'(Rp)&=R(T'p) &&\text{by (P5)},\\
&=R(\rho(T')p) &&\text{definition of }p,\\
&=\rho(T')Rp &&\text{linearity}.
\end{align}
Thus $Rp$ is also a strictly positive eigenvector for $\rho(T')$.  By the uniqueness part of (P6), after fixing the normalization of $p$,
\begin{align}
Rp&=p &&\text{for every Potts-label permutation }R.
\end{align}
Therefore
\begin{align}
p&\in\mathcal M &&\text{by (P7)}.
\end{align}
Since $\mathcal M$ is invariant under $T$ and $T'=T^2$,
\begin{align}
T'|_{\mathcal M}
&=T^2|_{\mathcal M} &&\text{by (P3)},\\
&=(T|_{\mathcal M})^2 &&\text{because }T\mathcal M\subseteq\mathcal M\text{ by (P4)},\\
&=T_2^2 &&\text{by (P4)}.
\end{align}
Hence $\rho(T')$ is the largest eigenvalue of $T_2^2$.  The eigenvalues $r$ of $T_2$ satisfy
\begin{align}
0&=\det\begin{pmatrix}u-r&w\\w&v-r\end{pmatrix} &&\text{definition of eigenvalue},\\
&=(u-r)(v-r)-w^2 &&\text{determinant of a }2\times2\text{ matrix},\\
&=r^2-(u+v)r+(uv-w^2) &&\text{expand}.
\end{align}
By the quadratic formula,
\begin{align}
r_\pm
&=\frac{u+v\pm\sqrt{(u+v)^2-4(uv-w^2)}}{2},\\
&=\frac{u+v}{2}\pm\frac{1}{2}\sqrt{u^2-2uv+v^2+4w^2},\\
&=\frac{u+v}{2}\pm\sqrt{\left(\frac{u-v}{2}\right)^2+w^2}.
\end{align}
Define
\begin{align}
A&:=\frac{u+v}{2}>0,\\
B&:=\sqrt{\left(\frac{u-v}{2}\right)^2+w^2}>0.
\end{align}
Then $r_+=A+B$ and $r_-=A-B$.  If $r_-\geq 0$, then
\begin{align}
|r_-|&=r_-<r_+.
\end{align}
If $r_-<0$, then
\begin{align}
|r_-|&=B-A<A+B=r_+ &&\text{because }A>0.
\end{align}
Thus
\begin{align}
\rho(T_2^2)&=r_+^2 &&\text{since }r_+>|r_-|,\\
\rho(T')&=r_+^2 &&\text{because the Perron vector of }T'\text{ lies in }\mathcal M.
\end{align}
Using the partition function,
\begin{align}
f&=\lim_{N\to\infty}-\frac{1}{2N\beta}\ln\operatorname{Tr}((T')^N) &&\text{by (P8)},\\
&=-\frac{1}{2\beta}\ln\rho(T') &&\text{by (P6) and (P9)},\\
&=-\frac{1}{2\beta}\ln(r_+^2) &&\text{by the preceding line},\\
&=-\frac{1}{\beta}\ln r_+ &&\text{because }r_+>0.
\end{align}
Substituting the expression for $r_+$ gives
\begin{align}
\lambda&:=r_+=\frac{u+v}{2}+\sqrt{\left(\frac{u-v}{2}\right)^2+w^2},\\
f&=-\frac{1}{\beta}\ln\lambda.
\end{align}

\section*{Final Result}
\[
\boxed{\lambda=\frac{u+v}{2}+\sqrt{\left(\frac{u-v}{2}\right)^2+w^2},\qquad f=-\frac{1}{\beta}\ln\lambda.}
\]
\hfill$\blacksquare$

core_reasoning_3:
\section*{Claim}
The one-dimensional $J_1-J_2$ $q$-state Potts chain and the one-dimensional $q$-state Potts chain with nearest-neighbor coupling $J_2$ and a field $J_1$ selecting Potts state $1$ have the same maximally symmetric transfer block
\[
\begin{pmatrix}
xy^2 & \sqrt{q-1}\,y\\
\sqrt{q-1}\,y & x+q-2
\end{pmatrix},
\]
and therefore the same largest transfer-matrix eigenvalue and the same thermodynamic free energy per spin.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &q\in\mathbb N,
\quad q\geq 2,
\quad \mathcal S:=\{1,\ldots,q\}.\\
\text{(P2)}\quad &x:=e^{\beta J_2}>0,
\quad y:=e^{\beta J_1/2}>0.\\
\text{(P3)}\quad &H_{\mathrm{field}}:=-J_2\sum_{i=1}^{2N}\delta(\sigma_i,\sigma_{i+1})-J_1\sum_{i=1}^{2N}\delta(\sigma_i,1).\\
\text{(P4)}\quad &K(a,b):=x^{\delta(a,b)}y^{\delta(a,1)+\delta(b,1)}
\quad\text{is the symmetrized one-step transfer matrix for }H_{\mathrm{field}}.\\
\text{(P5)}\quad &|\phi_1\rangle:=|1\rangle,
\qquad
|\phi_2\rangle:=\frac{1}{\sqrt{q-1}}\sum_{s=2}^{q}|s\rangle.\\
\text{(P6)}\quad &\text{For the }J_1-J_2\text{ chain, the largest-eigenvalue transfer block is }T_2=
\begin{pmatrix}xy^2&\sqrt{q-1}\,y\\\sqrt{q-1}\,y&x+q-2\end{pmatrix}.\\
\text{(P7)}\quad &\text{A finite positive transfer matrix has its largest eigenvector in the invariant subspace fixed by its label symmetries}.\\
\text{(P8)}\quad &\text{Both models have }2N\text{ sites and }f=-\beta^{-1}\ln\lambda\text{ when }\lambda\text{ is the largest one-step transfer eigenvalue}.
\end{aligned}
\]

\section*{Derivation}
The matrix element in the $|\phi_1\rangle$ direction is
\begin{align}
\langle\phi_1|K|\phi_1\rangle
&=K(1,1) &&\text{by (P5)},\\
&=x^{\delta(1,1)}y^{\delta(1,1)+\delta(1,1)} &&\text{by (P4)},\\
&=xy^2 &&\text{by }\delta(1,1)=1.
\end{align}
The off-diagonal matrix element is
\begin{align}
\langle\phi_1|K|\phi_2\rangle
&=\frac{1}{\sqrt{q-1}}\sum_{s=2}^{q}K(1,s) &&\text{by (P5)},\\
&=\frac{1}{\sqrt{q-1}}\sum_{s=2}^{q}x^{\delta(1,s)}y^{\delta(1,1)+\delta(s,1)} &&\text{by (P4)},\\
&=\frac{1}{\sqrt{q-1}}\sum_{s=2}^{q}y &&\text{since }s\ne 1,\\
&=\sqrt{q-1}\,y.
\end{align}
By symmetry of $K(a,b)$ in $a,b$,
\begin{align}
\langle\phi_2|K|\phi_1\rangle&=\sqrt{q-1}\,y.
\end{align}
The $|\phi_2\rangle$ matrix element is
\begin{align}
\langle\phi_2|K|\phi_2\rangle
&=\frac{1}{q-1}\sum_{r=2}^{q}\sum_{s=2}^{q}K(r,s) &&\text{by (P5)},\\
&=\frac{1}{q-1}\sum_{r=2}^{q}\sum_{s=2}^{q}x^{\delta(r,s)}y^{\delta(r,1)+\delta(s,1)} &&\text{by (P4)},\\
&=\frac{1}{q-1}\sum_{r=2}^{q}\sum_{s=2}^{q}x^{\delta(r,s)} &&\text{since }r,s\ne 1,\\
&=\frac{1}{q-1}\left((q-1)x+(q-1)(q-2)\right)\\
&=x+q-2.
\end{align}
Thus the field model has the block
\begin{align}
K_{\mathrm{MSS}}
&=\begin{pmatrix}
xy^2 & \sqrt{q-1}\,y\\
\sqrt{q-1}\,y & x+q-2
\end{pmatrix}.
\end{align}
Comparing with (P6),
\begin{align}
K_{\mathrm{MSS}}&=T_2.
\end{align}
By (P7), the largest eigenvalue of the positive field-model transfer matrix is the largest eigenvalue of $K_{\mathrm{MSS}}$, and the largest eigenvalue of the $J_1-J_2$ chain is the largest eigenvalue of $T_2$. Hence
\begin{align}
\lambda_{\mathrm{field}}&=\lambda_{J_1-J_2},\\
f_{\mathrm{field}}&=-\beta^{-1}\ln\lambda_{\mathrm{field}}
=-\beta^{-1}\ln\lambda_{J_1-J_2}
=f_{J_1-J_2} &&\text{by (P8)}.
\end{align}

\section*{Final Result}
\[
\boxed{K_{\mathrm{MSS}}=T_2=\begin{pmatrix}xy^2&\sqrt{q-1}\,y\\\sqrt{q-1}\,y&x+q-2\end{pmatrix},\qquad f_{\mathrm{field}}=f_{J_1-J_2}.}
\]
\hfill$\blacksquare$
